import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,X as d}from"./chunks/vendor-vueuse.XPft87tp.js";const b=JSON.parse('{"title":"Vue Router hash 模式与 history 模式的区别","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue-hash-vs-history.md","filePath":"vue/vue-hash-vs-history.md","lastUpdated":1786990830000}'),o={name:"vue/vue-hash-vs-history.md"};function h(i,e,r,c,n,l){return s(),a("div",null,e[0]||(e[0]=[d(`<h1 id="vue-router-hash-模式与-history-模式的区别" tabindex="-1">Vue Router hash 模式与 history 模式的区别 <a class="header-anchor" href="#vue-router-hash-模式与-history-模式的区别" aria-label="Permalink to &quot;Vue Router hash 模式与 history 模式的区别&quot;">​</a></h1><h3 id="hash-模式的工作原理" tabindex="-1">hash 模式的工作原理 <a class="header-anchor" href="#hash-模式的工作原理" aria-label="Permalink to &quot;hash 模式的工作原理&quot;">​</a></h3><p>hash 模式下的 URL 带有一个 <code>#</code> 符号，比如 <code>http://example.com/#/home</code>。<code>#</code> 及之后的部分不会发送给服务器，完全由浏览器本地处理。Vue Router 通过监听 <code>hashchange</code> 事件来感知路由变化，切换对应的组件。</p><p>hash 模式最大的优势是兼容性好，不需要服务端做任何配置。把打包好的静态文件往任意服务器一放就能跑，不用担心刷新 404。</p><p>但代价是 URL 不够美观，而且 <code>#</code> 在分享链接、SEO 等场景下不理想。另外，<code>#</code> 后面的内容无法参与 HTTP 请求，某些依赖锚点的逻辑需要额外处理。</p><h3 id="history-模式的工作原理" tabindex="-1">history 模式的工作原理 <a class="header-anchor" href="#history-模式的工作原理" aria-label="Permalink to &quot;history 模式的工作原理&quot;">​</a></h3><p>history 模式利用 HTML5 的 <code>pushState()</code> 和 <code>replaceState()</code> API 来修改浏览器地址栏，不再依赖 <code>#</code>，URL 看起来和正常的多页网站一样：<code>http://example.com/home</code>。</p><p>路由变化时，Vue Router 使用 <code>popstate</code> 事件感知浏览器的前进/后退操作，而 <code>pushState</code> / <code>replaceState</code> 本身不会触发 <code>popstate</code>。Vue Router 在前端内部维护了一套路由栈，手动调用 <code>router.push()</code> 或 <code>&lt;router-link&gt;</code> 时直接更新地址栏并渲染对应组件。</p><p>history 模式的致命弱点是刷新页面时，浏览器会向服务器请求当前 URL 对应的资源。如果服务端没有处理 fallback（比如 Nginx 把所有路径都指向 <code>index.html</code>），就会返回 404。</p><h3 id="关键差异对比" tabindex="-1">关键差异对比 <a class="header-anchor" href="#关键差异对比" aria-label="Permalink to &quot;关键差异对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>hash 模式</th><th>history 模式</th></tr></thead><tbody><tr><td>URL 形态</td><td><code>/#/home</code></td><td><code>/home</code></td></tr><tr><td>服务端依赖</td><td>不需要</td><td>需要 fallback 配置</td></tr><tr><td>实现机制</td><td><code>hashchange</code> 事件</td><td><code>pushState</code> + <code>popstate</code> 事件</td></tr><tr><td>兼容性</td><td>IE10+</td><td>IE10+</td></tr><tr><td>SEO</td><td>差（<code>#</code> 后内容不参与抓取）</td><td>好（前提是服务端渲染配合）</td></tr><tr><td>部署复杂度</td><td>低</td><td>中等（需要 Nginx/Apache 配置）</td></tr></tbody></table><h3 id="服务端-fallback-配置" tabindex="-1">服务端 fallback 配置 <a class="header-anchor" href="#服务端-fallback-配置" aria-label="Permalink to &quot;服务端 fallback 配置&quot;">​</a></h3><p>history 模式在生产环境常见的 Nginx 配置如下：</p><div class="language-nginx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> / </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  try_files </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$uri $uri/ /index.html;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这行配置的含义是：先尝试匹配请求的静态文件，找不到就回退到 <code>index.html</code>，由前端路由接管。如果缺少这个配置，用户在 <code>/about</code> 页面刷新就会看到一个 404。</p><h3 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h3><p>不需要 SEO、部署环境简单（比如 GitHub Pages 不支持配置 Nginx）时，hash 模式是更省心的选择。需要干净 URL 或对 SEO 有要求、服务端配置可控时，使用 history 模式。</p>`,17)]))}const k=t(o,[["render",h]]);export{b as __pageData,k as default};
